import sys
input = sys.stdin.read

def solve(data):
    index = 0
    T = int(data[index])
    index += 1
    results = []

    for _ in range(T):
        n, x = map(int, data[index:index+2])
        index += 2
        s = data[index]
        index += 1

        cnt0 = s.count('0')
        cnt1 = n - cnt0
        diff = cnt0 - cnt1

        current_balance = 0
        count = 0
        infinite = False

        # Check each prefix of the first complete s in t
        for c in s:
            if current_balance == x:
                count += 1
            if c == '0':
                current_balance += 1
            else:
                current_balance -= 1

        # Check if we found infinite solutions
        if diff == 0:
            if current_balance == x:
                infinite = True
        else:
            # Check prefixes of t beyond the first s
            for i in range(n + 1):
                if (x - current_balance) % diff == 0 and (x - current_balance) // diff >= 0:
                    count += 1
                if i < n:
                    if s[i] == '0':
                        current_balance += 1
                    else:
                        current_balance -= 1

        if infinite:
            results.append(-1)
        else:
            results.append(count)

    for result in results:
        print(result)

data = input().split()
