    prefix_count = 0
    prefix_sum = []

    for i in range(n):
        if s[i] == '0':
            balance += 1
        else:
            balance -= 1

        prefix_sum.append(balance)

    total_balance = prefix_sum[-1]

    if total_balance == 0:
        if x == 0:
            return -1
        else:
            return 0

    if total_balance > 0:
        for i in range(n):
            if (x - prefix_sum[i]) % total_balance == 0 and (x - prefix_sum[i]) / total_balance >= 0:
                prefix_count += 1
    else:
        x = -x
        total_balance = -total_balance
        for i in range(n):
            if (x - prefix_sum[i]) % total_balance == 0 and (x - prefix_sum[i]) / total_balance >= 0:
                prefix_count += 1

    return prefix_count

